content.content:
1	/* ============================ Tự khám phá: điều phối chế độ bay dù lượn ============================
2	   Nối flight (mô hình), glider (dù), chase (camera) với vòng animate, phím và URL.
3	   `?explore=glider` bay thẳng; không tham số (hoặc `?test&chooser`) hiện màn chọn; Esc tải lại trang không còn tham số explore. Camera do explore.update đặt sau updateCamera. */
4	import * as THREE from 'three';
5	import { scene, camera, controls, renderer } from '../core/renderer';
6	import { composer } from '../core/postprocessing';
7	import { cam, keys } from '../views/state';
8	import { exCreate, exStep, exInputFromKeys, type GliderState, type GliderInput } from './flight';
9	import { exBuildGlider, exPlaceGlider } from './glider';
10	import { plPreload, plReset, plSetWarm, plDebug } from './pilot';
11	import { exChase } from './chase';
12	import { exShowChooser } from './chooser';
13	import { exNight, exNightBind, exNightStep } from './nightShows';
14	import { exMulti } from './multi';
15	import { stroll, setupStroll } from './stroll';
16	import { drive, setupDrive } from './drive';
17	import { bike, setupBike } from './bike';
18	import { stAvatars } from './stroll/avatars';
19	import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from './multi/watch';
20	import { CONFIG } from '../config';
21	import type { SwingController } from '../bridges/song-han/SwingController';
22	
23	const _inp: GliderInput = { turn: 0, climb: 0, throttle: 0 };   // đầu vào tái dùng mỗi khung
24	
25	/* Làm nóng shader người treo có xương (D-018), như stroll/index.ts stRigSetWarm: hai biến thể (vẽ thẳng ra canvas ban ngày, vào render target của composer ban đêm),
26	   đèn / sương / bóng lấy từ cảnh chính, camera chính (đèn lọc theo lớp của nó). Cảnh nguồn không thêm vào scene */
27	plSetWarm(async (o: THREE.Object3D) => {
28	  const rt = renderer.getRenderTarget();
29	  renderer.setRenderTarget(null);
30	  const a = renderer.compileAsync(o, camera, scene);
31	  renderer.setRenderTarget(rt);
32	  await a;
33	  renderer.setRenderTarget(composer.readBuffer);
34	  const b = renderer.compileAsync(o, camera, scene);
35	  renderer.setRenderTarget(rt);
36	  await b;
37	});
38	
39	let glider: THREE.Group | null = null;
40	let state: GliderState | null = null;
41	let watching = false;   // đang xem người khác bay (hết chỗ hoặc vừa nhường chỗ): không có dù của mình, không đọc phím
42	let chased = false;     // camera đã bám người được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
43	let readout = '';   // chữ đang hiện ở #exSpeed: chỉ ghi DOM khi đổi
44	
45	const active = () => cam.mode === 'glider' && state !== null;
46	const inGlider = () => active() || watching;   // Esc và giao diện bay áp cho cả chế độ xem
47	
48	/* Mỗi khung khi xem: dù người khác, nhãn, danh sách; camera bám dù đang xem (không có người thì giữ nguyên) */
49	function watchStep(dt: number): void {
50	  exMulti.update(dt, performance.now(), null);
51	  const st = exMulti.watchState();
52	  if (st) { exChase(camera, controls.target, st, dt, !chased); chased = true; }
53	  exNightStep(dt);
54	}
55	
56	/* Đổi phiên khi đang xem hoặc bay: vào bay, mất kết nối, bị thu hồi chỗ */
57	function onMultiChange(): void {
58	  const s = exMulti.session; if (!s) return;
59	  if (watching) {
60	    if (s.phase === 'flying') { explore.start(); return; }   // chấp nhận lời mời: cất cánh mới như bay thường
61	    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lost'); } catch { /* bộ nhớ bị chặn */ } explore.exit(); return; }   // màn chọn đọc cờ này và hiện exMpLost
62	    exWatchRender();
63	  } else if (active()) {
64	    if (s.phase === 'watching') { state = null; if (glider) glider.visible = false; explore.startWatching(true); return; }   // chỗ bị thu hồi: sang xem, camera giữ nguyên
65	    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'exMpLost');   // vẫn bay, người khác đã biến mất
66	  }
67	}
68	
69	/* Đồng hồ tốc độ (km/h) và độ cao (m): chỉ số và đơn vị nên không cần dịch */
70	function exShowSpeed(): void {
71	  const t = `${Math.round(state!.speed * 3.6)} km/h · ${Math.round(state!.pos.y)} m`;
72	  if (t === readout) return;
73	  readout = t;
74	  const el = document.getElementById('exSpeed'); if (el) el.textContent = t;
75	}
76	
77	/* Một bước: mô phỏng, đặt dù, đặt camera bám */
78	function advance(dt: number, inp: GliderInput): void {
79	  exStep(state!, inp, dt);
80	  exPlaceGlider(glider!, state!, dt, inp);
81	  exChase(camera, controls.target, state!, dt);
82	  exShowSpeed();
83	  exNightStep(dt);
84	  exMulti.update(dt, performance.now(), state);   // dù người khác, nhãn tên, gửi vị trí (không làm gì khi bay một mình)
85	}
86	
87	export const explore = {
88	  active,
89	  nightShows: exNight,
90	  get state() { return state; },
91	  get glider() { return glider; },
92	  get watching() { return watching; },
93	  /* Cho test: số đo người treo của dù mình (pilot/index.ts plDebug); null khi chưa bay */
94	  pilotDebug() { return glider ? plDebug(glider) : null; },
95	  start(): void {
96	    plPreload();
97	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
98	    exMulti.onChange = onMultiChange;
99	    state = exCreate();
100	    const slot = exMulti.session ? exMulti.session.mySlot : -1;
