142	export function setupExplore(ctrl: SwingController): void {
143	  exNightBind(ctrl);
144	  setupStroll(ctrl, () => explore.exit());
145	  setupDrive(ctrl, () => explore.exit());
146	  setupBike(ctrl, () => explore.exit());
147	  window.addEventListener('keydown', (e) => {
148	    if (!inGlider() && !stroll.inMode() && !drive.inMode() && !bike.inMode()) return;
149	    if (e.key === 'Escape') { explore.exit(); return; }   // Esc thoát kể cả khi đang focus ô chọn (bay dù, đi dạo, lái xe, xe máy và hai chế độ xem)
150	    if (watching || stroll.inMode() || drive.inMode() || bike.inMode()) return;   // xem: không lái; đi dạo / lái xe / xe máy: phím do stroll/index.ts, drive/index.ts, bike/index.ts ghi
151	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt (Cmd+S...) không lái dù, tránh kẹt phím
152	    const t = e.target as HTMLElement | null;
153	    if (t && /^(SELECT|INPUT|TEXTAREA)$/.test(t.tagName)) return;   // phím trong ô chọn/nhập không lái dù
154	    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
155	    const k = e.key.toLowerCase(); keys.add(k);
156	    if (k.startsWith('arrow')) e.preventDefault();
157	  });
158	  /* Chọn ngôn ngữ / chất lượng bằng chuột xong thì bỏ focus, nếu không mũi tên và WASD sau đó đổi cài đặt thay vì lái dù. Dùng Tab + bàn phím thì giữ nguyên. */
159	  for (const id of ['langSelect', 'qualitySel']) {
160	    const sel = document.getElementById(id); if (!sel) continue;
161	    let byMouse = false;
162	    sel.addEventListener('pointerdown', () => { byMouse = true; });
163	    sel.addEventListener('keydown', () => { byMouse = false; });
164	    sel.addEventListener('change', () => { if (byMouse && (active() || stroll.active() || drive.active() || bike.active())) sel.blur(); byMouse = false; });
165	  }
166	  const q = new URLSearchParams(location.search);
167	  exNight.enabled = !q.has('test');   // test bật tường minh qua __app.explore.nightShows
168	  if (q.has('test')) document.body.classList.add('ex-test');   // giữ HUD khi bay để test đo draw call
169	  document.getElementById('btnExExit')?.addEventListener('click', () => explore.exit());
170	  if (q.get('explore') === 'glider') { explore.start(); return; }
171	  if (q.get('explore') === 'stroll') { stroll.start(); return; }   // đi dạo một mình, không qua slot
172	  if (q.get('explore') === 'drive') { drive.start(); return; }   // lái xe một mình
173	  if (q.get('explore') === 'bike') { bike.start(); return; }     // xe máy một mình
174	  if (!q.has('test') || q.has('chooser')) {
175	    document.querySelector('button[data-pick="walk"]')?.addEventListener('click', () => stAvatars.preload());   // chọn thẻ Đi dạo: nạp nhân vật của mình ngay, trong lúc ở sảnh
176	    document.querySelector('button[data-pick="glider"]')?.addEventListener('click', () => plPreload());   // chọn thẻ Dù lượn: nạp người treo ngay, trong lúc ở sảnh
177	    document.querySelector('button[data-pick="car"]')?.addEventListener('click', () => drive.preload());   // chọn thẻ Ô tô: nạp mô hình xe ngay
178	    document.querySelector('button[data-pick="bike"]')?.addEventListener('click', () => bike.preload());   // chọn thẻ Xe máy: nạp mô hình xe máy ngay (Task 3)
179	    exShowChooser((choice) => { if (choice === 'glider') explore.start(); else if (choice === 'walk') stroll.start(); else if (choice === 'car') drive.start(); else if (choice === 'bike') bike.start(); },
180	      (choice) => { if (choice === 'walk') stroll.startWatching(); else if (choice === 'car') drive.startWatching(); else if (choice === 'bike') bike.startWatching(); else explore.startWatching(); });   // 'guided': màn chọn tự ẩn, giao diện cũ
181	  }
182	}
