1	/* ============================ Lái xe: điều phối chế độ (lái một mình, máy tính) ============================
2	   Nối mạng đường (net / roadData / solids / sceneSolids), chuyển động + va chạm (motion / collide), hình xe (car / cars),
3	   camera sau xe (camera) với vòng animate, phím, chuột, cảm ứng (touch), HUD (hud: đồng hồ, bản đồ nhỏ, gợi ý), tiếng mô tơ / còi (sound). Mẫu: explore/stroll/index.ts.
4	   `?explore=drive` vào thẳng, lái một mình; thẻ "Ô tô" ở màn chọn: có máy chủ thì qua sảnh 5 chỗ lái (phiên kind 'drive'), không thì lái một mình.
5	   Esc và nút Thoát dùng explore.exit() (tải lại trang, D-020); trước đó drive.stop() trả lại các thứ đã đổi.
6	   - Mạng đường dựng MỘT lần ở lần đầu vào chế độ và giữ lại: ô tĩnh + vật cản tĩnh + nhà / chân đế thu từ cảnh (drCollectRuntime chỉ push,
7	     gọi hai lần sẽ nhân đôi vật cản). Chỉ đọc cảnh, sau mọi rand().
8	   - Barie Cầu sông Hàn: cổng DR_GATE_SWING của ô nhịp quay đóng khi cầu rời CLOSED (mỗi khung); không tự quay, không tăng tốc quay (như đi dạo).
9	     Xe đang chạm nhịp quay lúc đó được sơ tán ra ngoài barie gần nhất (motion.ts drEvacStep), gói trong thời gian còn lại trước khi nhịp xoay
10	     (drSwingBudget: coi như nhịp không phải chờ xe tự động rời nhịp, tức thời gian ngắn nhất).
11	   - Xe tự động: mỗi khung lấy hộp các xe đang hiện trong bán kính CONFIG.drive.ai.radius (common/trafficQuery.ts trNearby, mảng tái dùng);
12	     người chơi lao vào thì bị chặn, xe tự động chạy tới thì đi xuyên (collide.ts drMove).
13	   - Ban đêm Cầu Rồng tự phun như khi đi dạo (exNightStep, swing = false).
14	   - Hầm: driveView.far = CONFIG.drive.tunnelFar khi đang lái để mặt đường hầm hiện ở nút giao với hai đường dọc mới; thoát trả 1.
15	   - Xe của mình nằm trong drCars ở slot của mình (màu theo slot, multiParams.colors) hoặc slot 0 khi lái một mình; xe và bánh chỉ vào cảnh khi có xe (multi/index.ts gắn drCars.group
16	     theo exDrivers.onCars), góc nhìn cũ không thêm lệnh vẽ.
17	   - Nhiều người (exMulti, phiên kind 'drive'): xuất phát theo slot, gửi vị trí + vận tốc + góc lái sendHz lần/s (cả lúc đang sơ tán khỏi nhịp quay); xe người khác (exDrivers) không tham gia va chạm
18	     (chỉ vẽ, nhãn tên, chấm trên bản đồ nhỏ). Hết chỗ lái thì chế độ xem (startWatching): camera sau xe được xem, không điều khiển, đồng hồ + bản đồ theo xe đó; rời máy thì nhường chỗ sang xem.
19	   - Phím theo e.code (keys.ts), chỉ ghi khi đang lái, bỏ qua ô nhập và tổ hợp Ctrl / Meta / Alt; blur, ẩn tab, focus vào ô nhập thì nhả hết.
20	   - Cảm ứng (touch.ts, #drHud): đọc SAU phím và gộp (giá trị có độ lớn lớn hơn), không xóa phím trên máy lai; reset() cùng chỗ nhả phím. Phím H: còi.
21	   Mỗi khung không cấp phát (D-018). */
22	import type * as THREE from 'three';
23	import { scene, camera, controls, canvas, renderer } from '../../core/renderer';
24	import { composer, onResize } from '../../core/postprocessing';
25	import { cam } from '../../views/state';
26	import { CONFIG } from '../../config';
27	import { driveView } from '../../environment/driveRoads';
28	import { drMakeNet, drSetGate, type DrNet } from './net';
29	import { drBuildPads, DR_GATE_SWING } from './roadData';
30	import { drBuildSolids } from './solids';
31	import { drCollectRuntime, drSceneStats } from './sceneSolids';
32	import { drCreate, drStep, drEvacStep, type DrState, type DrInput } from './motion';
33	import { trNearby } from '../../common/trafficQuery';
34	import { drUseBody, DR_CAR_BODY, type DrBox } from './collide';
35	import { drCarLoad, drCarSetWarm } from './car';
36	import { drCars } from './cars';
37	import { drCamPlace, drCamDrag, type DrCam } from './camera';
38	import { drInputFromKeys, drBindDrop, DR_KEYS } from './keys';
39	import { drHudShow, drHudHide, drHudUpdate } from './hud';
40	import { drTouchBind } from './touch';
41	import { drSound } from './sound';
42	import { exNightStep } from '../nightShows';
43	import { exMulti } from '../multi';
44	import { exDrivers } from '../multi/remoteDrive';
45	import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from '../multi/watch';
46	import type { SwingController } from '../../bridges/song-han/SwingController';
47	
48	const DR_SOLO_SLOT = -1;     // drCreate / drSpawnPose: lái một mình xuất phát ở giữa các chỗ của slot
49	const DR_SELF = 0;           // slot xe của mình trong drCars khi lái một mình (màu slot 0); có chỗ thật thì dùng slot được cấp
50	
51	/* Làm nóng shader của xe (D-018), như stroll/index.ts stRigSetWarm: hai biến thể (vẽ thẳng ra canvas ban ngày, vào render target của composer ban đêm),
52	   đèn / sương / bóng lấy từ cảnh chính, camera chính (đèn lọc theo lớp của nó). Nhóm làm nóng do car.ts dựng, không thêm vào scene */
53	drCarSetWarm(async (o: THREE.Object3D) => {
54	  const rt = renderer.getRenderTarget();
55	  renderer.setRenderTarget(null);
56	  const a = renderer.compileAsync(o, camera, scene);
57	  renderer.setRenderTarget(rt);
58	  await a;
59	  renderer.setRenderTarget(composer.readBuffer);
60	  const b = renderer.compileAsync(o, camera, scene);
61	  renderer.setRenderTarget(rt);
62	  await b;
63	});
64	
65	let net: DrNet | null = null;
66	let state: DrState | null = null;
67	let ctrl: SwingController | null = null;
68	const drKeys = new Set<string>();  // e.code đang giữ
69	const camS: DrCam = { yaw: 0, pitch: 0, idle: 0 };
70	const _inp: DrInput = { gas: 0, brake: 0, steer: 0, hand: false };   // đầu vào tái dùng mỗi khung
71	let selfSlot = DR_SELF;            // slot xe của mình trong drCars
72	let watching = false;              // đang xem xe người khác (hết chỗ lái hoặc vừa nhường chỗ): không có xe của mình, không đọc phím
73	let chased = false;                // camera đã bám xe được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
74	let exit: () => void = () => {};   // thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem
75	const _ws = { x: 0, z: 0, yaw: 0, v: 0 };   // xe đang xem đưa cho HUD (đồng hồ, bản đồ nhỏ), tái dùng mỗi khung
76	let touch: ReturnType<typeof drTouchBind> | null = null;   // điều khiển cảm ứng (setupDrive dựng)
77	const boxes: DrBox[] = [];         // hộp xe tự động gần xe, tái dùng mỗi khung (trNearby chỉ thêm phần tử khi phải nới)
78	let saved: { fov: number; explore: boolean } | null = null;   // thứ start() đổi, stop() trả lại: fov camera, lớp body 'explore' đã có từ trước chưa
79	
80	const active = () => cam.mode === 'car' && state !== null;
81	const inMode = () => active() || watching;   // Esc và giao diện lái áp cho cả chế độ xem
82	const isField = (t: EventTarget | null) => !!t && /^(SELECT|INPUT|TEXTAREA)$/.test((t as HTMLElement).tagName || '');
83	
84	/* Mạng đường dựng lần đầu vào chế độ, giữ lại cho các lần sau; cổng nhịp quay theo cầu hiện tại.
85	   Dùng chung cho cả trang: chế độ xe máy (explore/bike) cũng gọi hàm này, không dựng net thứ hai (drCollectRuntime chỉ push) */
86	export function drEnsureNet(): DrNet {
87	  if (!net) {
88	    const n = drMakeNet(drBuildPads(), drBuildSolids());
89	    drCollectRuntime(n, (scene.getObjectByName('tp-houses') as THREE.InstancedMesh) || null);   // một lần cho mỗi net (chỉ push)
90	    net = n;                                                         // gán sau khi thu xong: thu lỗi thì lần vào sau thu lại từ đầu
91	  }
92	  if (ctrl) drSetGate(net, DR_GATE_SWING, ctrl.state !== 'CLOSED');
93	  return net;
94	}
95	
96	/* Giây (thời gian thật) còn lại tới lúc nhịp quay bắt đầu xoay (ROTATING_OPEN), giả sử nhịp không phải chờ xe tự động rời nhịp
97	   (spanClear đúng ngay: thời gian ngắn nhất); 0 khi nhịp đã / đang xoay hoặc cầu đóng: drEvacStep coi 0 là hết hạn (trượt trong evac.minTime), khác bỏ trống (không hạn) */
98	function drSwingBudget(c: SwingController): number {
99	  const T = c.cfg.timing, sp = c.speed > 0 ? c.speed : 1;
100	  if (c.state === 'STOP_TRAFFIC') return Math.max(0, T.amber + T.barrier - c.t + T.unlock) / sp;
101	  if (c.state === 'UNLOCK') return Math.max(0, T.unlock - c.t) / sp;
102	  return 0;
103	}
104	
105	/* Một bước: cổng nhịp quay, sơ tán / chuyển động, hình xe, camera, hiệu ứng đêm */
106	function advance(dt: number, inp: DrInput): void {
107	  if (ctrl) drSetGate(net!, DR_GATE_SWING, ctrl.state !== 'CLOSED');
108	  const s = state!;
109	  if (!drEvacStep(s, net!, dt, ctrl ? drSwingBudget(ctrl) : undefined)) drStep(s, inp, net!, boxes, trNearby(s.x, s.z, CONFIG.drive.ai.radius, boxes), dt);
110	  drCars.place(selfSlot, state!);
111	  drCamPlace(camera, state!, camS, net!, dt);
112	  controls.target.set(state!.x, state!.y, state!.z);   // tâm vùng bóng đổ (main.ts shadowCenter) theo xe
113	  const now = performance.now();
114	  exMulti.update(dt, now, null);     // xe người khác, người bay / đi dạo, nhãn tên; không làm gì khi lái một mình
115	  exMulti.updateDrive(now, state);   // gửi vị trí + vận tốc + góc lái khi đang giữ chỗ (kể cả lúc sơ tán)
116	  drHudUpdate(state!, exDrivers.dots()); drSound.update(state!.v);
117	  exNightStep(dt, false);
118	}
119	
120	/* Mỗi khung khi xem: xe người khác, nhãn, danh sách; camera sau xe được xem (hướng bám hướng xe đó), đồng hồ và bản đồ nhỏ theo xe đó. Không có ai thì giữ nguyên */
121	function watchStep(dt: number): void {
122	  if (ctrl) drSetGate(net!, DR_GATE_SWING, ctrl.state !== 'CLOSED');
123	  exMulti.update(dt, performance.now(), null);
124	  const w = exMulti.watchDriver();
125	  if (w) {
126	    drCamPlace(camera, w, camS, net!, dt, !chased); chased = true;
127	    controls.target.set(w.x, w.y, w.z);
128	    _ws.x = w.x; _ws.z = w.z; _ws.yaw = w.yaw; _ws.v = w.v;
129	    drHudUpdate(_ws, exDrivers.dots(w));
130	  }
131	  exNightStep(dt, false);
132	}
133	
134	/* Đổi phiên khi đang xem hoặc đang lái: vào lái, mất kết nối, bị thu hồi chỗ (như stOnMultiChange của đi dạo) */
135	function drOnMultiChange(): void {
136	  const s = exMulti.session; if (!s) return;
137	  if (watching) {
138	    if (s.phase === 'flying') { drive.start(); return; }   // chấp nhận lời mời: xuất phát như vào lái thường
139	    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lostDrive'); } catch { /* bộ nhớ bị chặn */ } exit(); return; }   // màn chọn đọc cờ này và hiện drLostChooser
140	    exWatchRender();
141	  } else if (active()) {
142	    if (s.phase === 'watching') { drive.startWatching(true); return; }   // chỗ bị thu hồi (rời máy): sang xem, camera giữ nguyên
143	    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'drLost');   // vẫn lái, người khác đã biến mất
144	  }
145	}
146	
147	/* Xe đứng yên ở (x, z) hướng yaw, trạng thái mới từ drCreate (xóa trạng thái cọ tường); y bỏ trống thì lấy mặt đường cao nhất tại đó.
148	   Dùng cho test (__app.drive) và đặt lại vị trí */
149	function drPlaceAt(x: number, z: number, yaw: number, y?: number): void {
150	  if (!net) return;
151	  const s = drCreate(net, DR_SOLO_SLOT);
152	  let gy = -Infinity;
153	  for (const p of net.pads) {
154	    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1 || (p.gate !== undefined && net.closed.has(p.gate))) continue;
155	    gy = Math.max(gy, p.y(x, z));
156	  }
157	  s.x = x; s.z = z; s.yaw = yaw; s.y = y ?? (Number.isFinite(gy) ? gy : CONFIG.roadY);
158	  state = s;
159	  camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
160	  drCars.place(selfSlot, s);
161	  drCamPlace(camera, s, camS, net, 0, true);
162	  controls.target.set(s.x, s.y, s.z);
163	}
164	
165	export const drive = {
166	  active,
167	  inMode,
168	  get watching(): boolean { return watching; },
169	  get state(): DrState | null { return state; },
170	  get net(): DrNet | null { return net; },
171	  get cam(): DrCam { return camS; },
172	  /* Vào lái: một mình (không phiên / ngoại tuyến) hoặc với slot lái vừa được cấp (xuất phát theo slot, màu xe theo slot) */
173	  start(): void {
174	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
175	    drUseBody(DR_CAR_BODY);   // thân va chạm ô tô (chế độ xe máy có thể đã đổi sang thân xe máy trong cùng trang)
176	    const n = drEnsureNet(), s = exMulti.session;
177	    const slot = s && s.kind === 'drive' && s.mySlot >= 0 ? s.mySlot : DR_SOLO_SLOT;
178	    if (s) exMulti.onChange = drOnMultiChange;
179	    selfSlot = slot >= 0 ? slot : DR_SELF;
180	    state = drCreate(n, slot);
181	    camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
182	    exDrivers.setSelf(selfSlot);   // dựng xe của mình; drCars.group vào cảnh nhờ exDrivers.onCars (multi/index.ts)
183	    drCars.place(selfSlot, state);
184	    driveView.far = CONFIG.drive.tunnelFar;
185	    drKeys.clear(); touch?.reset();
186	    drHudShow(n); drSound.start();
187	    if (!saved) saved = { fov: camera.fov, explore: document.body.classList.contains('explore') };
188	    cam.flight.then = null; cam.mode = 'car'; controls.enabled = false;
189	    camera.fov = CONFIG.drive.cam.fov; onResize();   // onResize cập nhật ma trận chiếu và hệ số cỡ điểm theo fov mới
190	    drCamPlace(camera, state, camS, n, 0, true);
191	    controls.target.set(state.x, state.y, state.z);
192	    document.body.classList.add('explore', 'drive');
193	  },
194	  /* Chế độ xem bám xe người khác (hết chỗ lái, hoặc vừa nhường chỗ do rời máy): cam.mode = 'car' nhưng không có xe / trạng thái của mình, không đọc phím, không tiếng mô tơ;
195	     carry = true khi vừa nhường chỗ (camera đang ở sau xe cũ, trượt dần sang xe được xem). Không có phiên thì không làm gì */
196	  startWatching(carry = false): void {
197	    const s = exMulti.session; if (!s) return;
198	    drUseBody(DR_CAR_BODY);
199	    const n = drEnsureNet();
200	    state = null; watching = true; chased = carry;
201	    drKeys.clear(); touch?.reset(); drSound.stop();
202	    exDrivers.setSelf(-1);
203	    driveView.far = CONFIG.drive.tunnelFar;
204	    drHudShow(n);
205	    if (!saved) saved = { fov: camera.fov, explore: document.body.classList.contains('explore') };
206	    cam.flight.then = null; cam.mode = 'car'; controls.enabled = false;
207	    camera.fov = CONFIG.drive.cam.fov; onResize();
208	    document.body.classList.add('explore', 'drive', 'ex-watching');
209	    exMulti.onChange = drOnMultiChange;
210	    exWatchShow(s);
211	  },
212	  update(dt: number): void {
213	    if (watching) { watchStep(dt); return; }
214	    if (!active()) return;
215	    drInputFromKeys(drKeys, _inp);
216	    if (touch) touch.read(_inp);   // gộp, không xóa phím
217	    drSound.horn(drKeys.has('KeyH'));
218	    advance(dt, _inp);
219	  },
220	  /* Gọi ngay sau lệnh vẽ khung chính (main.ts); chỗ cho HUD / chụp ảnh của task sau */
221	  afterRender(): void { /* chưa có việc */ },
222	  /* Rời chế độ: trả mọi thứ đã đổi (explore.exit tải lại trang ngay sau), kể cả khi cam.mode đã bị chỗ khác đổi khỏi 'car' */
223	  stop(): void {
224	    if (state === null && !watching) return;
225	    state = null; drKeys.clear(); touch?.reset();
226	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
227	    drHudHide(); drSound.stop();
228	    exDrivers.clear(); drCars.clear(); drCars.group.removeFromParent();
229	    driveView.far = 1;
230	    document.body.classList.remove('drive');
231	    if (saved) {
232	      if (!saved.explore) document.body.classList.remove('explore');
233	      camera.fov = saved.fov; onResize();                            // onResize tính lại ma trận chiếu và pScale theo fov cũ
234	      saved = null;
235	    }
236	    if (cam.mode === 'car') { cam.mode = 'orbit'; controls.enabled = true; }
237	  },
238	  /* Cho test: như update nhưng nhận đầu vào trực tiếp; đặt xe tại chỗ */
239	  step(dt: number, inp: DrInput): void { if (active()) advance(dt, inp); },
240	  placeAt: drPlaceAt,
241	  stats: drSceneStats,
242	  preload(): void { void drCarLoad(); }
243	};
244	
245	/* onExit: thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem */
246	export function setupDrive(c: SwingController, onExit: () => void): void {
247	  ctrl = c; exit = onExit;
248	  window.addEventListener('keydown', (e) => {
249	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung)
250	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt không điều khiển xe, tránh kẹt phím
251	    if (isField(e.target)) return;                    // gõ trong ô nhập / chọn không điều khiển xe
252	    if (!DR_KEYS.has(e.code)) return;
253	    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
254	    if (e.code.startsWith('Arrow') || e.code === 'Space') e.preventDefault();   // không cuộn trang, Space không bấm nút đang focus
255	    drKeys.add(e.code);
256	  });
257	  window.addEventListener('keyup', (e) => {
258	    drKeys.delete(e.code);
259	    if (e.code === 'Space' && active() && !isField(e.target)) e.preventDefault();
260	  });
261	  const drop = drBindDrop(window, document, drKeys);
262	  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) { drop(); touch?.reset(); drSound.horn(false); } });
263	  /* Tab ẩn hoặc mất tiêu điểm: vòng khung có thể dừng nên tắt còi ngay (phím đã nhả ở drBindDrop, cảm ứng tự reset trong touch.ts) */
264	  window.addEventListener('blur', () => drSound.horn(false));
265	  document.addEventListener('visibilitychange', () => { if (document.hidden) drSound.horn(false); });
266	  drSound.bind(document.getElementById('drSoundBtn'), () => cam.mode !== 'bike');   // nút 🔊 / 🔇: cách duy nhất bật tiếng xe khi chưa bật âm thanh chung (nút nhạc ẩn trong chế độ khám phá)
267	  const hud = document.getElementById('drHud');
268	  if (hud) touch = drTouchBind(hud, {
269	    look: (dx, dy) => { if (active()) drCamDrag(camS, dx, dy); },
270	    activity: () => exMulti.activity()
271	  });
272	  /* Kéo chuột trái trên canvas: xoay camera quanh xe (ngón tay vuốt #drLook trong touch.ts) */
273	  let dragId = -1, lx = 0, ly = 0;
274	  canvas.addEventListener('pointerdown', (e) => {
275	    if (!active() || e.pointerType === 'touch' || e.button !== 0) return;
276	    dragId = e.pointerId; lx = e.clientX; ly = e.clientY;
277	    canvas.setPointerCapture(e.pointerId);
278	  });
279	  canvas.addEventListener('pointermove', (e) => {
280	    if (e.pointerId !== dragId) return;
281	    drCamDrag(camS, e.clientX - lx, e.clientY - ly);
282	    lx = e.clientX; ly = e.clientY;
283	  });
284	  const end = (e: PointerEvent) => { if (e.pointerId === dragId) dragId = -1; };
285	  canvas.addEventListener('pointerup', end);
286	  canvas.addEventListener('pointercancel', end);
287	  canvas.addEventListener('lostpointercapture', end);
288	}
