178	/* Âm thanh: điền BkSoundIn từ trạng thái xe (không cấp phát); bkSound tự giới hạn số lần ghi tham số (updateMs) */
179	function soundStep(s: BkState, nNear: number, tunnel: boolean, dry: boolean): void {
180	  _snd.v = s.v; _snd.rpm = s.rpm; _snd.throttle = s.throttle; _snd.brakeK = s.brakeK; _snd.sig = s.sig;
181	  _snd.sus = Math.max(Math.abs(s.susF), Math.abs(s.susR));
182	  _snd.rain = dry ? 0 : weatherU.uRain.value; _snd.tunnel = tunnel; _snd.river = bkRiverK(s.x);
183	  _snd.view = camB.view; _snd.nNear = nNear; _snd.x = s.x; _snd.z = s.z; _snd.yaw = s.yaw; _snd.t = shared.uTime.value;
184	  bkSound.update(_snd);
185	}
186	
187	/* Xe đang ở ô hầm không: ô chứa (x, z) có cao độ gần y nhất trong ± stepMax (như drive/net.ts drPadAt), kiểu 'tunnel'. Duyệt tuyến tính, không cấp phát */
188	function bkInTunnel(n: DrNet, s: BkState): boolean {
189	  const step = CONFIG.drive.stepMax;
190	  let best = -1, bestD = Infinity;
191	  for (let i = 0; i < n.pads.length; i++) {
192	    const p = n.pads[i];
193	    if (s.x < p.x0 || s.x > p.x1 || s.z < p.z0 || s.z > p.z1 || (p.gate !== undefined && n.closed.has(p.gate))) continue;
194	    const d = Math.abs(p.y(s.x, s.z) - s.y);
195	    if (d <= step && d < bestD) { best = i; bestD = d; }
196	  }
197	  return best >= 0 && n.pads[best].kind === 'tunnel';
198	}
199	/* Trong ô hầm thì đã ở đoạn có mái chưa (ngoài |x| > coverHalf là dốc hở: mưa, mặt ướt) */
200	const bkCovered = (s: BkState): boolean => Math.abs(s.x) <= HR.coverHalf;
201	
202	/* Người lái theo xe (sau model.place): tín hiệu từ trạng thái chuyển động */
203	function riderStep(s: BkState, dt: number): void {
204	  if (!rider || !model) return;
205	  _sig.lean = s.lean; _sig.acc = s.acc; _sig.susF = s.susF; _sig.susR = s.susR; _sig.steer = s.steer;
206	  rider.update(model, _sig, dt);
207	}
208	
209	/* Mắt góc thứ nhất theo người lái: đo một lần khi có người lái thật trên mô hình thật. Đặt xe về tư thế nghỉ (thẳng đứng, không lái, giảm xóc 0),
210	   người lái tư thế ngồi nền (lò xo phản ứng chưa chạy với người mới), giữa hai xương mắt (+ cam1.eyeFore; không có thì xương đầu + cam1.headEye)
211	   → hệ thân xe (nhóm ngoài: yaw · dốc, dốc = 0); rồi đặt lại như cũ */
212	function riderEye(): void {
213	  const s = state, r = rider, m = model;
214	  if (!r || !m || !m.real) { if (eyeFor) { eyeFor = null; bkCamSetEye(null); } return; }
215	  if (eyeFor === r || !s) return;
216	  eyeFor = r;
217	  _rest.x = s.x; _rest.y = s.y; _rest.z = s.z; _rest.yaw = s.yaw;
218	  m.place(_rest);
219	  r.update(m, _sig0, 0);
220	  r.setFirstPerson(false);
221	  const eyes = r.eyeLocal(m.group, _eye);
222	  bkCamSetEye(eyes ? { fore: _eye.x + C1.eyeFore, up: _eye.y } : { fore: _eye.x + C1.headEye.fore, up: _eye.y + C1.headEye.up });
223	  m.place(s);
224	  riderStep(s, 0);
225	}
226	
227	/* Nạp người lái theo nhân vật đã chọn (stChar, chung với Đi dạo). Về sau stop() / start() khác thì bỏ; nhân vật đổi thì thay người cũ */
228	function riderNeed(): void {
229	  const ch = stChar.get(), gen = ++riderGen;
230	  if (rider && riderCh === ch) return;
231	  void bkRiderLoad(ch).then((src) => {
232	    if (gen !== riderGen || state === null || !src) return;
233	    try {
234	      const r = new BkRider(src);
235	      rider?.dispose(); rider = r; riderCh = ch;
236	      riderStep(state, 0);
237	    } catch (e) { console.warn('Lái xe máy: không dựng được người lái', e); }
238	  });
239	}
240	
241	/* Xe đứng yên ở (x, z) hướng yaw, trạng thái mới; y bỏ trống thì lấy mặt đường cao nhất tại đó. Cho test (__app.bike) và đặt lại vị trí */
242	function bkPlaceAt(x: number, z: number, yaw: number, y?: number): void {
243	  if (!net || !model) return;
244	  const s = bkCreate(net, BK_SOLO_SLOT);
245	  let gy = -Infinity;
246	  for (const p of net.pads) {
247	    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1 || (p.gate !== undefined && net.closed.has(p.gate))) continue;
248	    gy = Math.max(gy, p.y(x, z));
249	  }
250	  s.x = x; s.z = z; s.yaw = yaw; s.y = y ?? (Number.isFinite(gy) ? gy : CONFIG.roadY);
251	  bkPitch(s, net);
252	  state = s;
253	  bkCamReset();
254	  model.place(s);
255	  riderStep(s, 0);
256	  riderEye();
257	  if (bkCamPlace(camera, s, camB, net, 0, true)) onResize();
258	  controls.target.set(s.x, s.y, s.z);
259	}
260	
261	/* Trạng thái camera về đầu (giữ góc nhìn đang chọn, trộn xong ngay) */
262	function bkCamReset(): void {
263	  const v = camB.view;
264	  Object.assign(camB, bkCamCreate());
265	  camB.view = v; camB.mix = v === 3 ? 1 : 0;
266	}
267	
268	export const bike = {
269	  active,
270	  inMode,
271	  get state(): BkState | null { return state; },
272	  get net(): DrNet | null { return net; },
273	  get model(): BkBike | null { return model; },   // hình xe của mình (test: real, anchors)
274	  get rider(): BkRider | null { return rider; },  // người lái (test: debug(), setFirstPerson)
275	  get view(): 1 | 3 { return camB.view; },
276	  get cam(): BkCam { return camB; },               // test: mix, roll, bob, surge, yaw / pitch nhìn quanh
277	  get dash(): BkDash | null { return dash; },
278	  get cfg(): typeof CONFIG.bike { return CONFIG.bike; },   // test / kiểm tay: chỉnh số camera lúc chạy
279	  get sound(): typeof bkSound { return bkSound; },        // test: nodes(), on, graph
280	  get fx(): typeof bkFx { return bkFx; },                 // test: drawn() (vệt pha, số hạt bụi nước), group
281	  get input(): Readonly<BkInput> { return _inp; },        // test: đầu vào của khung gần nhất (grip theo mặt ướt / hầm kín)
282	  /* Đổi góc nhìn: trộn vị trí + hướng + fov + near trong cam1.mixS, không dừng xe */
283	  setView(v: 1 | 3): void { camB.view = v === 3 ? 3 : 1; },
284	  get watching(): boolean { return watching; },
285	  /* Vào lái: một mình (không phiên / ngoại tuyến) hoặc với slot lái vừa được cấp (xuất phát theo slot) */
286	  start(): void {
287	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
288	    const n = drEnsureNet();   // dựng net trước: lỗi ở đây thì thân va chạm vẫn là ô tô (mạng đường không phụ thuộc thân xe)
289	    drUseBody(BK_BODY);
290	    net = n;
291	    const ses = exMulti.session;
292	    const slot = ses && ses.kind === 'drive' && ses.mySlot >= 0 ? ses.mySlot : BK_SOLO_SLOT;
293	    if (ses) exMulti.onChange = bkOnMultiChange;
294	    exDrivers.setSelf(-1);    // xe của mình không nằm trong drCars (model.ts vẽ)
295	    state = bkCreate(n, slot);
296	    camB.view = 1; bkCamReset();
297	    motionK = typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches ? C1.motionReduced : C1.motion;
298	    if (!model) model = new BkBike();
299	    if (!dash) dash = new BkDash();
300	    scene.add(model.group);
301	    model.place(state);
302	    scene.add(bkFx.group); bkFx.start(n);
303	    bkRoadSet(true);                          // hạt nhựa + vệt ướt trên vật liệu đường (roadFx.ts; uRoadNear = 1 nếu CONFIG.bike.road.detail)
304	    riderNeed();
305	    riderStep(state, 0);
306	    driveView.far = CONFIG.drive.tunnelFar;   // mặt đường hầm hiện ở nút giao với hai đường dọc mới, như ô tô
307	    bkKeys.clear(); touch?.reset(); hornTouch = false;
308	    drHudShow(n); bkHudShow(); bkSound.start();
309	    if (!saved) saved = { fov: camera.fov, near: camera.near, explore: document.body.classList.contains('explore') };
310	    cam.flight.then = null; cam.mode = 'bike'; controls.enabled = false;
311	    riderEye();
312	    bkCamPlace(camera, state, camB, n, 0, true); onResize();   // fov / near góc thứ nhất; onResize cập nhật ma trận chiếu và hệ số cỡ điểm
313	    controls.target.set(state.x, state.y, state.z);
314	    document.body.classList.add('explore', 'drive', 'bike');
315	  },
316	  /* Chế độ xem bám xe người khác (hết chỗ lái, hoặc vừa nhường chỗ do rời máy): cam.mode = 'bike' nhưng không có xe / trạng thái của mình, không đọc phím, không tiếng máy;
317	     carry = true khi vừa nhường chỗ (camera đang ở sau xe cũ, trượt dần sang xe được xem). Không có phiên thì không làm gì */
318	  startWatching(carry = false): void {
319	    const s = exMulti.session; if (!s) return;
320	    const n = drEnsureNet();
321	    net = n;
322	    if (state !== null) {   // vừa nhường chỗ: cất xe, người lái, hiệu ứng, tiếng của mình
323	      riderGen++; rider?.setFirstPerson(false);
324	      model?.group.removeFromParent(); bkFx.stop(); bkSound.stop(); bkHudHide();
325	    }
326	    state = null; watching = true; chased = carry;
327	    bkKeys.clear(); touch?.reset(); hornTouch = false;
328	    bkRoadSet(false);                         // hạt nhựa + vệt ướt chỉ khi tự lái
329	    exDrivers.setSelf(-1);
330	    driveView.far = CONFIG.drive.tunnelFar;
331	    drHudShow(n);
332	    if (!saved) saved = { fov: camera.fov, near: camera.near, explore: document.body.classList.contains('explore') };
333	    cam.flight.then = null; cam.mode = 'bike'; controls.enabled = false;
334	    camW.yaw = 0; camW.pitch = 0; camW.idle = 0;
335	    document.body.classList.add('explore', 'drive', 'bike', 'ex-watching');
336	    exMulti.onChange = bkOnMultiChange;
337	    exWatchShow(s);
338	  },
339	  update(dt: number): void {
340	    if (watching) { watchStep(dt); return; }

