3	   Không cần trả lại show.on khi rời dù: thoát dù là tải lại trang (D-020). */
4	import { CONFIG } from '../config';
5	import { dayNight } from '../core/dayNight';
6	import { show } from '../bridges/dragon/effects';
7	import type { SwingController } from '../bridges/song-han/SwingController';
