9	/* enabled: tắt khi có ?test để các phép đo đêm không dao động; rest: số giây nghỉ còn lại trước lượt quay tiếp */
10	export const exNight = { enabled: true, rest: 0, show };
11	
12	let ctrl: SwingController | null = null;
13	export function exNightBind(c: SwingController): void { ctrl = c; }
14	
15	/* Gọi mỗi bước bay / đi dạo; swing = false (đi dạo): chỉ phun lửa / nước, không tự quay và không tăng tốc Cầu sông Hàn (spec đi dạo §3 mục 13) */
16	export function exNightStep(dt: number, swing = true): void {
17	  if (!exNight.enabled || !ctrl) return;
18	  const C = CONFIG.explore.nightShows, night = dayNight.target > 0.5;
19	  if (show.on !== night) { show.on = night; show.t = 0; }   // đổi trời: bắt đầu lại từ lần phun đầu
20	  if (!swing) return;
21	  if (ctrl.state !== 'CLOSED') {                            // đang quay (cả khi đã sang ngày): đi nốt tới khi đóng
22	    ctrl.speed = C.swingSpeed;
23	    if (ctrl.state === 'OPEN') ctrl.requestClose();
24	    exNight.rest = C.swingRest;
25	    return;
26	  }
27	  if (!night) return;
28	  exNight.rest = Math.max(0, exNight.rest - dt);
29	  if (exNight.rest === 0 && ctrl.canStart()) ctrl.start(C.swingSpeed);   // hỏi canStart trước để bão không phát swingBlocked mỗi khung
30	}
