// Kiểm tạm Task 2 (không commit): start() → 30 khung → stop() cho bốn chế độ, ba vòng.
const ROOT = 'file:///D:/2026%20-%20Tuan/danang-vite/.worktrees/intro-dien-anh/';
const { serveDir, launch, openApp, frames } = await import(ROOT + 'tests/lib.mjs');
import { fileURLToPath } from 'node:url';

const problems = [];
const check = (name, ok, extra = '') => { if (!ok) problems.push(name); console.log(`${ok ? 'đạt ' : 'LỖI '} ${name}${extra ? ' — ' + extra : ''}`); };

const srv = await serveDir(fileURLToPath(new URL('dist/', ROOT)));
const browser = await launch();
const { page, errors } = await openApp(browser, srv.url, { width: 960, height: 540 });
page.setDefaultTimeout(120000);
await frames(page, 10);

const calls = () => page.evaluate(async () => {
  await new Promise((ok) => requestAnimationFrame(() => requestAnimationFrame(ok)));
  return window.__app.renderer.info.render.calls;
});
const pose = () => page.evaluate(() => { const a = window.__app; return { p: a.camera.position.toArray(), t: a.controls.target.toArray() }; });
const setPose = (ps) => page.evaluate((ps) => { const a = window.__app; a.camera.position.fromArray(ps.p); a.controls.target.fromArray(ps.t); a.camera.lookAt(a.controls.target); a.controls.update(); }, ps);

const p0 = await pose();
const c0 = await calls();
console.log('lệnh vẽ trước:', c0, 'cam.mode', await page.evaluate(() => window.__app.cam.mode));

const MODES = {
  glider: { start: 'a.explore.start()', stop: 'a.explore.stop()' },
  stroll: { start: 'a.stroll.stroll.start()', stop: 'a.stroll.stroll.stop()' },
  drive: { start: 'a.drive.start()', stop: 'a.drive.stop()' },
  bike: { start: 'a.bike.start()', stop: 'a.bike.stop()' },
};
for (let round = 1; round <= 3; round++) {
  for (const [name, m] of Object.entries(MODES)) {
    // stop() khi chưa start(): không làm gì
    await page.evaluate((s) => { const a = window.__app; new Function('a', s)(a); }, m.stop);
    await page.evaluate((s) => { const a = window.__app; new Function('a', s)(a); }, m.start);
    const inMode = await page.evaluate(() => ({ mode: window.__app.cam.mode, cls: document.body.className }));
    await frames(page, 30);
    await page.evaluate((s) => { const a = window.__app; new Function('a', s)(a); new Function('a', s)(a); }, m.stop);   // gọi hai lần
    const r = await page.evaluate(() => { const a = window.__app; return { mode: a.cam.mode, fov: a.camera.fov, near: a.camera.near, cls: document.body.className, ctl: a.controls.enabled }; });
    await setPose(p0);
    const c = await calls();
    const tag = `vòng ${round} ${name}`;
    check(`${tag}: lúc chạy cam.mode ≠ orbit`, inMode.mode !== 'orbit', `${inMode.mode} [${inMode.cls}]`);
    check(`${tag}: cam.mode orbit + controls`, r.mode === 'orbit' && r.ctl, `${r.mode} ${r.ctl}`);
    check(`${tag}: fov 50, near 0.5`, r.fov === 50 && r.near === 0.5, `${r.fov} ${r.near}`);
    check(`${tag}: body sạch`, !/\b(explore|stroll|drive|bike)\b/.test(r.cls), `[${r.cls}]`);
    check(`${tag}: lệnh vẽ = trước`, c === c0, `${c} so với ${c0}`);
  }
}
check('console sạch', errors.length === 0, errors.slice(0, 5).join(' | '));
await browser.close(); srv.close();
console.log(problems.length ? `LỖI ${problems.length}` : 'TẤT CẢ ĐẠT');
process.exit(problems.length ? 1 : 0);

